head.script:
scwin.onpageload = function () {

	let tabOpt = {
		label: "트리뷰",
		openAction: "select",
		closable: "true"
	};

	let opt = {

		frameMode: "wframe",
		alwaysDraw: false,
		src: "/sample/common_link/treeview_tabControl_virtual_WESF-21_(WSQ-5589)_sub1.xml"
	};

	tab_outline.addTab("tabControl1", tabOpt, opt)

	let tabOpt2 = {
		label: "캘린더",
		openAction: "new",
		closable: "true"
	};

	let opt2 = {

		frameMode: "wframe",
		alwaysDraw: false,
		src: "/sample/common_link/treeview_tabControl_virtual_WESF-21_(WSQ-5589)_sub2.xml"
	};

	tab_outline.addTab("tabControl2", tabOpt2, opt2)
};

scwin.checkVal = function() {
	return (document.getElementById('tab_outline_contents_tabControl1_body_trv_menu_main_div') || document.getElementById('mf_tab_outline_contents_tabControl1_body_trv_menu_main_div')).children.length == 3;
};
